insert into public.device_catalog_manufacturers(name,slug,categories,source_system)
select n,trim(both '-' from regexp_replace(lower(n),'[^a-z0-9]+','-','g')),c,'curated' from source
on conflict(slug) do update set categories=excluded.categories,active=true,updated_at=now();

