insert into public.device_catalog_models(manufacturer_id,category,name,family,release_year,model_numbers,colors,storage_options,source_system)
select dm.id,s.c,s.n,s.f,s.y,s.mn,s.co,s.st,'curated'
from source s join public.device_catalog_manufacturers dm on lower(dm.name)=lower(s.m)
on conflict(manufacturer_id,category,name) do update set family=excluded.family,release_year=excluded.release_year,model_numbers=excluded.model_numbers,colors=excluded.colors,storage_options=excluded.storage_options,active=true,updated_at=now();